package estate.svc;

import estate.api.Context;
import estate.api.Service;
import estate.api.ServiceException;

import java.math.BigInteger;
import java.util.Map;

/** Decision: a risk score for a credit request. Stateless. Score runs from 0 (worst) to 1000 (best). */
public class Main implements Service {
    private static final BigInteger MAX_SCORE = BigInteger.valueOf(1000);

    @Override
    public void start(Context c) {}

    @Override
    public Map<String, String> handle(String op, Map<String, String> req) throws ServiceException {
        switch (op) {
            case "health": return Map.of("status", "UP");
            case "score": return score(req);
            default: throw new ServiceException("error", "unknown op " + op);
        }
    }

    private Map<String, String> score(Map<String, String> req) throws ServiceException {
        try {
            BigInteger income = integer(req.get("income"));
            BigInteger amount = integer(req.get("amount"));
            if (income.signum() <= 0) throw new ServiceException("error", "income must be positive");
            BigInteger rawScore = MAX_SCORE.subtract(amount.multiply(MAX_SCORE).divide(income));
            BigInteger score = rawScore.max(BigInteger.ZERO).min(MAX_SCORE);
            return Map.of("score", score.toString());
        } catch (NumberFormatException e) {
            throw new ServiceException("error", "bad number");
        }
    }

    private BigInteger integer(String value) {
        if (value == null) throw new NumberFormatException("missing number");
        return new BigInteger(value);
    }
}
